/**
 * The avatar options pack: every character, eye option, accessory and colour the designer offers, with the
 * geometry the composer needs. Ships in the app (shared/avatar/pack-v1.ts, generated by
 * scripts/avatar/build-pack.mjs from designer-b chars.js) so the designer opens with no network; the server
 * reports its `packVersion` and the app downloads a newer pack once.
 *
 * Pure data and lookups; imports nothing.
 */

/** [fill, path d]. Paths are drawn with fill-rule evenodd. */
export type PackPath = [fill: string, d: string];
/** [x, y, width, height] in character units (as SVG getBBox). */
export type PackBox = [x: number, y: number, w: number, h: number];

export interface PackCharacter {
  id: string;
  name: string;
  body: PackPath[];
  details: PackPath[];
  /** One path per eye, as drawn. */
  eyes: PackPath[];
  /** This character's own accessory (empty when it has none). */
  accessory: PackPath[];
  /** The eye option that looks like this character's own eyes (the designer hides it; Original shows that look). */
  ownEyes: string;
  geo: {
    body: PackBox;
    acc: PackBox | null;
    /** Each eye's box, left to right, with the index of its path in `eyes`. */
    eyes: Array<[x: number, y: number, w: number, h: number, index: number]>;
    /** Body + details + eyes. */
    naked: PackBox;
    /** The avatar square [x, y, size]: the naked figure and its own accessory, with room to move accessories. */
    frame: [x: number, y: number, size: number];
  };
}

export interface PackAccessory {
  /** Slug of its name, e.g. "box-cap". */
  id: string;
  name: string;
  /** The character it was drawn on (its art is that character's `accessory`). */
  from: string;
}

export interface AvatarPack {
  packVersion: number;
  source: { file: string; md5: string };
  /** [hex, name]; the "Original" colour is the absence of a colour. */
  palette: Array<[hex: string, name: string]>;
  /** [id, name]: "original", "dot", "pill", "closed", "happy", "wide", and "from:<character>" borrowed eyes. */
  eyes: Array<[id: string, name: string]>;
  accessories: PackAccessory[];
  characters: PackCharacter[];
}

/** Fast lookups over a pack (built once per pack object). */
export interface PackIndex {
  pack: AvatarPack;
  character: Map<string, PackCharacter>;
  accessory: Map<string, PackAccessory>;
  eyes: Set<string>;
  colours: Set<string>;
}

const indexes = new WeakMap<AvatarPack, PackIndex>();

export function packIndex(pack: AvatarPack): PackIndex {
  let ix = indexes.get(pack);
  if (!ix) {
    ix = {
      pack,
      character: new Map(pack.characters.map((c) => [c.id, c])),
      accessory: new Map(pack.accessories.map((a) => [a.id, a])),
      eyes: new Set(pack.eyes.map(([id]) => id)),
      colours: new Set(pack.palette.map(([hex]) => hex.toUpperCase())),
    };
    indexes.set(pack, ix);
  }
  return ix;
}

/** The eye options to show for a character (its own look is hidden: Original already shows it). */
export function eyeOptionsFor(pack: AvatarPack, characterId: string): Array<[id: string, name: string]> {
  const own = packIndex(pack).character.get(characterId)?.ownEyes;
  return pack.eyes.filter(([id]) => id !== own);
}
